'use client';

import type { VariantProps } from 'class-variance-authority';
import { cva } from 'class-variance-authority';
import {
  type EditorContentProps,
  type EditorPreviewProps,
  NodeSelectionDrag,
  NodeSelectionHighlight,
  EditorContainer as EditorContainerPrimitive,
  EditorContent,
  EditorPreview,
} from 'platejs/react';
import * as React from 'react';

import { cn } from '@/lib/utils';

const editorContainerVariants = cva(
  'relative w-full cursor-text select-text overflow-y-auto caret-primary selection:bg-brand/25 focus-visible:outline-none',
  {
    defaultVariants: {
      variant: 'default',
    },
    variants: {
      variant: {
        comment: cn(
          'flex flex-wrap justify-between gap-1 px-1 py-0.5 text-sm',
          'rounded-md border-[1.5px] border-transparent bg-transparent',
          'has-[[data-editor]:focus]:border-brand/50 has-[[data-editor]:focus]:ring-2 has-[[data-editor]:focus]:ring-brand/30',
          'has-aria-disabled:border-input has-aria-disabled:bg-muted'
        ),
        default: 'min-h-0 flex-1',
        select: cn(
          'group rounded-md border border-input ring-offset-background focus-within:ring-2 focus-within:ring-ring focus-within:ring-offset-2',
          'has-data-readonly:w-fit has-data-readonly:cursor-default has-data-readonly:border-transparent has-data-readonly:focus-within:[box-shadow:none]'
        ),
      },
    },
  }
);

export function EditorFrame({
  className,
  ...props
}: React.ComponentProps<'div'>) {
  return (
    <div
      className={cn('relative flex h-full min-h-0 w-full flex-col', className)}
      data-slot="editor-frame"
      {...props}
    />
  );
}

export function EditorContainer({
  className,
  variant,
  ...props
}: React.ComponentProps<'div'> & VariantProps<typeof editorContainerVariants>) {
  return (
    <EditorContainerPrimitive
      className={cn(
        'ignore-click-outside/toolbar',
        editorContainerVariants({ variant }),
        className
      )}
      data-slot="editor-container"
      {...props}
    />
  );
}

const editorVariants = cva(
  cn(
    'group/editor ignore-click-outside/toolbar',
    'relative w-full cursor-text select-text overflow-x-hidden whitespace-break-spaces break-words',
    'rounded-md ring-offset-background focus-visible:outline-none',
    '**:data-editor-placeholder:!top-1/2 **:data-editor-placeholder:-translate-y-1/2 placeholder:text-muted-foreground/80 **:data-editor-placeholder:text-muted-foreground/80 **:data-editor-placeholder:opacity-100! **:data-editor-drop-cursor:z-20 **:data-editor-drop-cursor:rounded-full **:data-editor-drop-cursor:bg-brand **:data-editor-inactive-selection:bg-brand/25 **:data-editor-inactive-selection-caret:z-20 **:data-editor-inactive-selection-caret:w-0.5 **:data-editor-inactive-selection-caret:bg-primary',
    '[&_strong]:font-bold'
  ),
  {
    defaultVariants: {
      variant: 'default',
    },
    variants: {
      disabled: {
        true: 'cursor-not-allowed opacity-50',
      },
      focused: {
        true: 'ring-2 ring-ring ring-offset-2',
      },
      variant: {
        ai: 'w-full px-0 text-base md:text-sm',
        aiChat:
          'max-h-[min(70vh,320px)] w-full overflow-y-auto px-3 py-2 text-base md:text-sm',
        comment: cn('rounded-none border-none bg-transparent text-sm'),
        default:
          'size-full px-16 pt-4 pb-72 text-base sm:px-[max(64px,calc(50%-350px))]',
        demo: 'size-full px-16 pt-4 pb-72 text-base sm:px-[max(64px,calc(50%-350px))]',
        fullWidth: 'size-full px-16 pt-4 pb-72 text-base sm:px-24',
        none: '',
        select: 'px-3 py-2 text-base data-readonly:w-fit',
      },
    },
  }
);

export function Editor({
  className,
  disabled,
  focused,
  variant,
  ref,
  ...props
}: (EditorContentProps & VariantProps<typeof editorVariants>) & {
  ref?: React.Ref<HTMLDivElement>;
}) {
  return (
    <>
      <EditorContent
        ref={ref}
        className={cn(
          editorVariants({
            disabled,
            focused,
            variant,
          }),
          className
        )}
        disabled={disabled}
        disableDefaultStyles
        {...props}
      />
      <NodeSelectionHighlight className="z-1 bg-brand/[.13]" />
      <NodeSelectionDrag className="z-50 border border-brand/25 bg-brand/15" />
    </>
  );
}

export function EditorView({
  className,
  variant,
  ...props
}: EditorPreviewProps<unknown> & VariantProps<typeof editorVariants>) {
  return (
    <EditorPreview
      {...props}
      className={cn(editorVariants({ variant }), className)}
    />
  );
}
